# B1 Preliminary: ek okuma çalışmaları (özgün metinler; sınav biçimi: kısa metinler, eşleştirme, uzun metin, cümle yerleştirme, cloze, açık boşluk)
def mk(k,id,t,ty,nm,ins,**o):
    d={'k':k,'id':id,'t':t,'ty':ty,'nm':nm,'ti':'Reading Part '+k[1],'ins':ins};d.update(o);return d
def m(x,q,o,a,tg,e):return {'x':x,'q':q,'o':o,'a':a,'tg':tg,'e':e}
